'use strict';

// MODULES //

var tape = require( 'tape' );
var isSameArray = require( '@stdlib/assert/is-same-array' );
var instanceOf = require( '@stdlib/assert/instance-of' );
var base = require( '@stdlib/ndarray/base/ctor' );
var ndarray = require( '@stdlib/ndarray/ctor' );
var nulls = require( '@stdlib/ndarray/base/nulls' );
var zeros = require( '@stdlib/ndarray/base/zeros' );
var getShape = require( '@stdlib/ndarray/shape' );
var getDType = require( '@stdlib/ndarray/dtype' );
var getData = require( '@stdlib/ndarray/data-buffer' );
var getOrder = require( '@stdlib/ndarray/order' );
var nullsLike = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof nullsLike, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function throws an error if provided a value having an unrecognized data type', function test( t ) {
	var values;
	var i;

	values = [
		'5',
		5,
		true,
		false,
		null,
		void 0,
		[],
		{},
		function noop() {},
		{
			'data': true
		},
		{
			'shape': [ 1, 2, 3 ],
			'order': 'row-major',
			'dtype': 'foo_bar_beep_boop'
		}
	];

	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[i] ), TypeError, 'throws an error when provided '+values[i] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			nullsLike( value );
		};
	}
});

tape( 'the function throws an error if provided an ndarray with a non-generic data type', function test( t ) {
	var dtypes;
	var i;

	dtypes = [
		'float64',
		'float32',
		'int32',
		'int16',
		'int8',
		'uint32',
		'uint16',
		'uint8',
		'uint8c'
	];

	for ( i = 0; i < dtypes.length; i++ ) {
		t.throws( badValue( dtypes[i] ), TypeError, 'throws an error when provided dtype='+dtypes[i] );
	}
	t.end();

	function badValue( dt ) {
		return function badValue() {
			nullsLike( zeros( dt, [ 2, 2 ], 'row-major' ) );
		};
	}
});

tape( 'the function returns a null-filled array (dtype=generic, order=row-major, base)', function test( t ) {
	var expected;
	var arr;
	var x;

	expected = [ null, null, null, null ];

	x = nulls( 'generic', [ 2, 2 ], 'row-major' );
	arr = nullsLike( x );

	t.strictEqual( instanceOf( arr, base ), true, 'returns expected value' );
	t.strictEqual( String( getDType( arr ) ), 'generic', 'returns expected value' );
	t.deepEqual( getShape( arr ), [ 2, 2 ], 'returns expected value' );
	t.strictEqual( instanceOf( getData( arr ), Array ), true, 'returns expected value' );
	t.strictEqual( isSameArray( getData( arr ), expected ), true, 'returns expected value' );
	t.strictEqual( getOrder( arr ), 'row-major', 'returns expected value' );

	t.end();
});

