tape( 'the function returns a null-filled array (dtype=generic, order=row-major, non-base)', function test( t ) {
	var expected;
	var arr;
	var x;

	expected = [ null, null, null, null ];

	x = new ndarray( 'generic', [ null, null, null, null ], [ 2, 2 ], [ 2, 1 ], 0, 'row-major' );
	arr = nullsLike( x );

	t.strictEqual( instanceOf( arr, ndarray ), true, 'returns expected value' );
	t.strictEqual( String( getDType( arr ) ), 'generic', 'returns expected value' );
	t.deepEqual( getShape( arr ), [ 2, 2 ], 'returns expected value' );
	t.strictEqual( instanceOf( getData( arr ), Array ), true, 'returns expected value' );
	t.strictEqual( isSameArray( getData( arr ), expected ), true, 'returns expected value' );
	t.strictEqual( getOrder( arr ), 'row-major', 'returns expected value' );

	t.end();
});

tape( 'the function returns a null-filled array (dtype=generic, order=column-major, non-base)', function test( t ) {
	var expected;
	var arr;
	var x;

	expected = [ null, null, null, null ];

	x = new ndarray( 'generic', [ null, null, null, null ], [ 2, 2 ], [ 1, 2 ], 0, 'column-major' );
	arr = nullsLike( x );

	t.strictEqual( instanceOf( arr, ndarray ), true, 'returns expected value' );
	t.strictEqual( String( getDType( arr ) ), 'generic', 'returns expected value' );
	t.deepEqual( getShape( arr ), [ 2, 2 ], 'returns expected value' );
	t.strictEqual( instanceOf( getData( arr ), Array ), true, 'returns expected value' );
	t.strictEqual( isSameArray( getData( arr ), expected ), true, 'returns expected value' );
	t.strictEqual( getOrder( arr ), 'column-major', 'returns expected value' );

	t.end();
});

tape( 'the function returns a new array distinct from the input', function test( t ) {
	var arr;
	var x;

	x = nulls( 'generic', [ 2, 2 ], 'row-major' );
	arr = nullsLike( x );

	t.notStrictEqual( arr, x, 'returns a different object' );
	t.notStrictEqual( getData( arr ), getData( x ), 'returns a different data buffer' );

	t.end();
});

tape( 'the function does not mutate the input array', function test( t ) {
	var buf;
	var arr;
	var x;

	buf = [ 1, 2, 3, 4 ];
	x = new ndarray( 'generic', buf, [ 2, 2 ], [ 2, 1 ], 0, 'row-major' );
	arr = nullsLike( x );

	t.ok( arr, 'returns an array' );
	t.deepEqual( getData( x ), [ 1, 2, 3, 4 ], 'input data unchanged' );

	t.end();
});

tape( 'the function supports zero-dimensional arrays', function test( t ) {
	var expected;
	var arr;
	var x;

	expected = [ null ];

	x = new ndarray( 'generic', [ null ], [], [ 0 ], 0, 'row-major' );
	arr = nullsLike( x );

	t.strictEqual( instanceOf( arr, ndarray ), true, 'returns expected value' );
	t.strictEqual( String( getDType( arr ) ), 'generic', 'returns expected value' );
	t.deepEqual( getShape( arr ), [], 'returns expected value' );
	t.strictEqual( instanceOf( getData( arr ), Array ), true, 'returns expected value' );
	t.strictEqual( isSameArray( getData( arr ), expected ), true, 'returns expected value' );
	t.strictEqual( getOrder( arr ), 'row-major', 'returns expected value' );

	t.end();
});

tape( 'the function supports empty arrays', function test( t ) {
	var expected;
	var arr;
	var x;

	expected = [];

	x = new ndarray( 'generic', [], [ 2, 0, 2 ], [ 0, 2, 1 ], 0, 'row-major' );
	arr = nullsLike( x );

	t.strictEqual( instanceOf( arr, ndarray ), true, 'returns expected value' );
	t.strictEqual( String( getDType( arr ) ), 'generic', 'returns expected value' );
	t.deepEqual( getShape( arr ), [ 2, 0, 2 ], 'returns expected value' );
	t.strictEqual( instanceOf( getData( arr ), Array ), true, 'returns expected value' );
	t.strictEqual( isSameArray( getData( arr ), expected ), true, 'returns expected value' );
	t.strictEqual( getOrder( arr ), 'row-major', 'returns expected value' );

	t.end();
});
